const fs = require("fs")
const zlib = require("zlib")

function paeth(a, b, c) {
  const p = a + b - c
  const pa = Math.abs(p - a)
  const pb = Math.abs(p - b)
  const pc = Math.abs(p - c)
  if (pa <= pb && pa <= pc) return a
  if (pb <= pc) return b
  return c
}

function decode(f) {
  const b = fs.readFileSync(f)
  let p = 8
  let w = 0
  let h = 0
  let ch = 3
  const idat = []
  while (p < b.length) {
    const len = b.readUInt32BE(p)
    const type = b.toString("ascii", p + 4, p + 8)
    const d = b.slice(p + 8, p + 8 + len)
    if (type === "IHDR") {
      w = d.readUInt32BE(0)
      h = d.readUInt32BE(4)
      const ct = d[9]
      ch = ct === 6 ? 4 : ct === 2 ? 3 : ct === 0 ? 1 : 3
    }
    if (type === "IDAT") idat.push(d)
    p += 12 + len
  }
  const raw = zlib.inflateSync(Buffer.concat(idat))
  const stride = w * ch
  const out = Buffer.alloc(h * stride)
  for (let y = 0; y < h; y++) {
    const ft = raw[y * (stride + 1)]
    const line = raw.slice(y * (stride + 1) + 1, y * (stride + 1) + 1 + stride)
    const cur = out.slice(y * stride, (y + 1) * stride)
    const prev = y ? out.slice((y - 1) * stride, y * stride) : Buffer.alloc(stride)
    for (let x = 0; x < stride; x++) {
      const a = x >= ch ? cur[x - ch] : 0
      const bb = prev[x]
      const c = x >= ch ? prev[x - ch] : 0
      let v = line[x]
      if (ft === 1) v += a
      else if (ft === 2) v += bb
      else if (ft === 3) v += (a + bb) >> 1
      else if (ft === 4) v += paeth(a, bb, c)
      cur[x] = v & 255
    }
  }
  return { w, h, ch, data: out }
}

const f = process.argv[2]
const img = decode(f)
const { w, h, ch, data } = img
const nonWhite = (x, y) => {
  const i = (y * w + x) * ch
  return data[i] < 245 || data[i + 1] < 245 || data[i + 2] < 245
}
let cols = []
for (let x = 0; x < w; x++) {
  let n = 0
  for (let y = 0; y < h; y++) if (nonWhite(x, y)) n++
  if (n > 10) cols.push(x)
}
if (!cols.length) {
  console.log("all white")
  process.exit(0)
}
let runs = []
let start = cols[0]
let prev = cols[0]
for (let k = 1; k < cols.length; k++) {
  if (cols[k] > prev + 4) {
    runs.push([start, prev])
    start = cols[k]
  }
  prev = cols[k]
}
runs.push([start, prev])
console.log(f, "size", w + "x" + h, "runs:", JSON.stringify(runs))

